// Volume Value Terrain Signal Analysis Model
// Volume-profile-at-price engine: POC + value-area expansion, breakout signals.

rowsIn = input(24, "Profile Rows", 10, 48, 1)
vaPctIn = input(70, "Value Area Percent", 50, 90, 5)
sessMode = input("Visible Chart", "Session Mode")
visLen = input(250, "Visible Session Bars", 50, 500, 10)
extendLines = input(true, "Extend POC/VAH/VAL Right")
showHist = input(true, "Show Value Histogram")
enable3D = input(true, "Enable 3D Terrain")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Session range: visible-chart window ─────────────────────────
sessHigh = highest(high, visLen)
sessLow = lowest(low, visLen)
rng = sessHigh - sessLow
if rng <= 0 {
    rng := close * 0.01
}
binH = rng / rowsIn

// ─── Persistent volume-at-price bins (literal init only) ─────────
var binVol = array()
var binsReady = 0.0

if binsReady == 0.0 {
    i = 0
    while i < rowsIn {
        array.push(binVol, 0.0)
        i := i + 1
    }
    binsReady := 1.0
}

// Reset bins each bar then rebuild from session window (close-based distribution)
i = 0
while i < rowsIn {
    array.set(binVol, i, 0.0)
    i := i + 1
}
k = 0
while k < visLen {
    c = close[k]
    v = volume[k]
    bi = floor((c - sessLow) / rng * rowsIn)
    if bi < 0 {
        bi := 0
    }
    if bi > rowsIn - 1 {
        bi := rowsIn - 1
    }
    array.set(binVol, bi, array.get(binVol, bi) + v)
    k := k + 1
}

// ─── Point of control: bin with max volume ───────────────────────
pocBin = 0
pocVal = array.get(binVol, 0)
i = 1
while i < rowsIn {
    vv = array.get(binVol, i)
    if vv > pocVal {
        pocVal := vv
        pocBin := i
    }
    i := i + 1
}
totalVol = array.sum(binVol)
pocShare = 0.0
if totalVol > 0 {
    pocShare := pocVal / totalVol
}
pocPrice = sessLow + (pocBin + 0.5) / rowsIn * rng

// ─── Value area: expand from POC until >= vaPct of total ─────────
vaLowB = pocBin
vaHighB = pocBin
accum = pocVal
target = totalVol * vaPctIn / 100
guard = 0
while accum < target and guard < rowsIn {
    leftV = 0 - 1.0
    if vaLowB > 0 {
        leftV := array.get(binVol, vaLowB - 1)
    }
    rightV = 0 - 1.0
    if vaHighB < rowsIn - 1 {
        rightV := array.get(binVol, vaHighB + 1)
    }
    if rightV >= leftV and vaHighB < rowsIn - 1 {
        vaHighB := vaHighB + 1
        accum := accum + rightV
    } else {
        if vaLowB > 0 {
            vaLowB := vaLowB - 1
            accum := accum + leftV
        }
    }
    guard := guard + 1
}
vahPrice = sessLow + (vaHighB + 1) / rowsIn * rng
valPrice = sessLow + vaLowB / rowsIn * rng

// ─── Terrain height: value concentration projected to price scale ─
terrSurf = sessLow + pocShare * rng + (pocBin + 0.5) / rowsIn * rng * 0.15
terrSurf := sessLow + (terrSurf - sessLow) * 0.5 + (vahPrice - valPrice) * pocShare * 0.5

insideNow = close >= valPrice and close <= vahPrice
prevClose = close[1]
prevVah = vahPrice[1]
prevVal = valPrice[1]
wasInside = prevClose >= prevVal and prevClose <= prevVah

buySig = wasInside and close > vahPrice and not insideNow
sellSig = wasInside and close < valPrice and not insideNow

// ─── 2D signal markers (inside conditionals) ─────────────────────
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}

// ─── 3D cones in same pane ───────────────────────────────────────
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 1, "3d")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 1, "3d")
}

// Rare standout label: first breakout after long balance
var insideCount = 0.0
if insideNow {
    insideCount := insideCount + 1
} else {
    insideCount := 0
}
if buySig and insideCount[1] > 20 {
    label3d(bar_index, high, "Breakout", "#22cc88", 1.0, 1, "3d")
}
if sellSig and insideCount[1] > 20 {
    label3d(bar_index, low, "Breakdown", "#ff4477", 1.0, 1, "3d")
}
if bar_index % 50 == 0 {
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.2, 1, "3d")
}

// ─── 2D rendering (unconditional, same values as 3D) ─────────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(pocShare * rng + sessLow, "POC Share", "#b48cff", 1, "separate")
plot(close, "Close", "#ffffff", 1)

// Value zone shading between VAH and VAL
box.new(bar_index[10], vahPrice, bar_index, valPrice, "#22cc8800", "rgba(34,204,136,0.08)", 1, "vahbox")

// ─── 3D rendering: terrain + POC labelled rail + VA edge rails ───
plot3d(terrSurf, "Value Terrain", "surface", "#22cc88", "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(vahPrice, "VAH Rail", "line3d", "#22cc88", "3d", 2)

// FIX: var lvl = highest(high, 20) froze the level on bar 0 — plain assignment recomputes every bar.
// FIX: close[-1] reads the future and repaints — corrected to close for a confirmed breakout.
// FIX: plotshape(true, low, "Buy", shape.triangleup, color.green) is Pine — corrected to OakScript positional string args.
// FIX: oscillator in pane="3d" renders as spiky forest over price — moved RSI geometry to pane="separate".
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

lvl = highest(high, 20)
r = rsi(close, 14)
buySig = close > lvl
osSig = crossover(r, 30)

if buySig {
  plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
  plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "separate")
}
if osSig {
  plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
  plotshape_3d(bar_index, low, "OS", "coneup", "#22cc88", 1.0 * markerSize, 0, "separate")
}

plot(r, "RSI", "#b48cff", 1, "line")
hline(30, "#22cc88")
plot3d(r, "RSI", "surface", "#b48cff", "separate")

basePsi = input(140, "Base PSI", 50, 250, 1)
critThr = input(150, "Critical Threshold", 100, 250, 1)
spinFactor = input(0.5, "Base Spin Factor", 0.05, 2.0, 0.05)
maxRings = input(5, "Max Rings", 1, 5, 1)
ringRate = input(2.0, "Ring Expansion Rate", 0.2, 5.0, 0.1)
textOff = input(2.5, "Text Height Offset", 0.5, 10.0, 0.1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

priceMove = close - open
flow_psi = basePsi + priceMove
spin_speed = flow_psi * spinFactor
locked = flow_psi > critThr
discLevel = close
overPrice = high + textOff

var rot = 0.0
var lockBars = 0.0

if locked {
    rot := rot[1]
} else {
    rot := rot[1] + spin_speed
}

if locked {
    lockBars := lockBars[1] + 1.0
} else {
    lockBars := 0.0
}

ring1Size = 0.6 + lockBars * 0.12 * ringRate
ring2Size = 0.6 + (lockBars - 2.0) * 0.12 * ringRate
ring3Size = 0.6 + (lockBars - 4.0) * 0.12 * ringRate
ring4Size = 0.6 + (lockBars - 6.0) * 0.12 * ringRate
ring5Size = 0.6 + (lockBars - 8.0) * 0.12 * ringRate
overSig = locked and not locked[1]
normSig = not locked and locked[1]

if overSig and not overSig[1] {
    plotshape(bar_index, high, "Overpressure", "triangledown", "#ff4477")
    plotshape_3d(bar_index, high, "Overpressure", "conedown", "#ff4477", 1.0 * markerSize, 2, "3d", 0, 0, 0)
}

if normSig and not normSig[1] {
    plotshape(bar_index, low, "Normalized", "triangleup", "#22cc88")
    plotshape_3d(bar_index, low, "Normalized", "coneup", "#22cc88", 1.0 * markerSize, 2, "3d", 0, 0, 0)
}

if overSig and not overSig[1] {
    label3d(bar_index, overPrice, "OVERPRESSURE", "#ff4477", 1, 3, "3d")
}

if locked and not locked[1] {
    plotshape_3d(bar_index, discLevel, "DiscLocked", "torus", "#ff4477", 1.0, 0, "3d", 90, rot, 0)
}
if not locked and locked[1] {
    plotshape_3d(bar_index, discLevel, "DiscSpin", "torus", "#22aaff", 1.0, 0, "3d", 90, rot, 0)
}

if locked and not locked[1] {
    plotshape_3d(bar_index, discLevel, "Ring1", "torus", "#ff9944", ring1Size, 1, "3d", 90, 0, 0)
}

if locked {
    if lockBars > 2.0 {
        plotshape_3d(bar_index, discLevel, "Ring2", "torus", "#ff9944", ring2Size, 1, "3d", 90, 0, 0)
    }
    if lockBars > 4.0 {
        plotshape_3d(bar_index, discLevel, "Ring3", "torus", "#ffcc44", ring3Size, 1, "3d", 90, 0, 0)
    }
    if lockBars > 6.0 {
        plotshape_3d(bar_index, discLevel, "Ring4", "torus", "#ffcc44", ring4Size, 1, "3d", 90, 0, 0)
    }
    if lockBars > 8.0 {
        plotshape_3d(bar_index, discLevel, "Ring5", "torus", "#ffffff", ring5Size, 1, "3d", 90, 0, 0)
    }
}

plot(flow_psi, "Flow PSI", "#22aaff", 2)
plot(spin_speed, "Spin Speed", "#33ddff", 1)
plot(discLevel, "Disc Price", "#888888", 1)
hline(critThr, "#ff4477")
plot3d(discLevel, "Disc Plane", "surface", "#22aaff", "3d", 0)
plot3d(flow_psi, "Pressure Spine", "line3d", "#ff4477", "3d", 1)
